351→    #[test]
352→    fn state_store_save_and_load() {
353→        let temp = TempDir::new().unwrap();
354→        let project = ProjectId::from_path(temp.path()).unwrap();
355→
356→        let mut state = StateStore::new(&project);
357→        state.update_step(
358→            "test_step",
359→            StepState {
360→                status: StepStatus::Success,
361→                last_run: Some(Utc::now()),
362→                duration_ms: Some(1000),
363→                watches_hash: None,
364→            },
365→        );
366→
367→        state.save(&project).unwrap();
368→
369→        let loaded = StateStore::load(&project).unwrap();
370→        assert!(loaded.get_step("test_step").is_some());
