397→    #[test]
398→    fn save_uses_atomic_write() {
399→        let temp = TempDir::new().unwrap();
400→        let project = ProjectId::from_path(temp.path()).unwrap();
401→
402→        let mut state = StateStore::new(&project);
403→        state.update_step(
404→            "test_step",
405→            StepState {
406→                status: StepStatus::Success,
407→                ..Default::default()
408→            },
409→        );
410→
411→        // Save state
412→        state.save(&project).unwrap();
413→
414→        // Verify no temp file remains (it should have been renamed)
415→        let temp_path = StateStore::state_file(&project).with_extension("yml.tmp");
416→        assert!(
417→            !temp_path.exists(),
