        };
        state.record_run(record);

        // Add the kept step state
        state.record_step_result("kept", StepStatus::Success, std::time::Duration::ZERO, None);

        state.cleanup(50);

        assert!(state.get_step("orphan").is_none());
        assert!(state.get_step("kept").is_some());
    }

